import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { ProductKey } from '~/queries/schema/schema-general'

import {
    RecipientTimelineEvent,
    RecipientTimelineRow,
    recipientTimelineQuery,
    toRecipientTimelineEvent,
} from './recipientTimelineQuery'

export interface RecipientTimelineLogicProps {
    email: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recipientTimelineLogicValues {
    loadFailed: boolean
    timeline: RecipientTimelineEvent[] | null
    timelineLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recipientTimelineLogicActions {
    loadRecipientTimeline: () => any
    loadRecipientTimelineFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRecipientTimelineSuccess: (
        timeline: RecipientTimelineEvent[],
        payload?: any
    ) => {
        timeline: RecipientTimelineEvent[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recipientTimelineLogicMeta {
    key: string
}

export type recipientTimelineLogicType = MakeLogicType<
    recipientTimelineLogicValues,
    recipientTimelineLogicActions,
    RecipientTimelineLogicProps,
    recipientTimelineLogicMeta
>

export const recipientTimelineLogic: LogicWrapper<recipientTimelineLogicType> = kea<recipientTimelineLogicType>([
    props({} as RecipientTimelineLogicProps),
    key((props) => props.email),
    path((key) => ['products', 'workflows', 'frontend', 'Audience', 'recipientTimelineLogic', key]),
    loaders(({ props }) => ({
        timeline: [
            null as RecipientTimelineEvent[] | null,
            {
                loadRecipientTimeline: async (_, breakpoint): Promise<RecipientTimelineEvent[]> => {
                    try {
                        const response = await api.queryHogQL<RecipientTimelineRow[]>(
                            recipientTimelineQuery(props.email),
                            { scene: 'Audience', productKey: ProductKey.WORKFLOWS, name: 'audience_recipient_timeline' }
                        )
                        breakpoint()
                        return response.results.map(toRecipientTimelineEvent)
                    } catch (error) {
                        breakpoint()
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        loadFailed: [
            false,
            {
                loadRecipientTimeline: () => false,
                loadRecipientTimelineSuccess: () => false,
                loadRecipientTimelineFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadRecipientTimeline()
    }),
])
